#!/usr/bin/env bash
# Copyright (C) 2026 Tornis Desenvolvimento
# SPDX-License-Identifier: AGPL-3.0-only
#
# Vendor the registry's Fluent Bit plugin catalogue into the core (ADR-074
# decision 2a). The catalogue is the ALLOWLIST — what a package may run and
# which parameters an operator may set — so it ships inside the binary, like
# the signing keyring, and changes only through a reviewed core release; a
# compromised registry cannot widen it. The registry publishes it unsigned
# and unindexed, which is fine for its CI and wrong for a trust decision.
#
#   ./.github/scripts/vendor-plugin-catalog.sh /path/to/veloxsearch-registry
#
# Copies fluent-bit/<version>/**/*.yaml (newest version) into
# crates/velox-integrations/fluent-bit/ and regenerates the include_str!
# table in crates/velox-integrations/src/spec2_catalog.rs. The test
# `vendored_catalogue_matches_the_registry` fails while the two differ.
set -euo pipefail
cd "$(dirname "$0")/../.."

reg=${1:?usage: $0 /path/to/veloxsearch-registry}
src=$(ls -d "$reg"/fluent-bit/*/ | sort -V | tail -1)
version=$(basename "$src")
dst=crates/velox-integrations/fluent-bit
rm -rf "$dst"
mkdir -p "$dst/$version"
(cd "$src" && find . -name '*.yaml' -print0 | sort -z | xargs -0 -I{} cp --parents {} "$OLDPWD/$dst/$version/")

out=crates/velox-integrations/src/spec2_catalog.rs
{
  echo '// Copyright (C) 2026 Tornis Desenvolvimento'
  echo '// SPDX-License-Identifier: AGPL-3.0-only'
  echo '//! GENERATED by `.github/scripts/vendor-plugin-catalog.sh` — do not edit.'
  echo '//! The vendored Fluent Bit plugin catalogue (ADR-074 decision 2a).'
  echo
  echo "/// The Fluent Bit documentation version the catalogue was transcribed from."
  echo "pub const VERSION: &str = \"$version\";"
  echo
  echo '/// `(path relative to fluent-bit/<VERSION>/, YAML)` for every plugin.'
  echo 'pub const FILES: &[(&str, &str)] = &['
  (cd "$dst/$version" && find . -name '*.yaml' | sed 's|^\./||' | sort) | while read -r f; do
    echo "    (\"$f\", include_str!(\"../fluent-bit/$version/$f\")),"
  done
  echo '];'
} > "$out"
echo "vendored $(grep -c include_str "$out") plugins from $src (version $version)"
